+fn main() {
+    if let Err(err) = run() {
+        error(&err);
+        process::exit(1);
+    }
+}
+
+fn run() -> Result<(), String> {
+    let cli = Cli::parse();
+
+    if cli.snapshot_type == SnapshotType::Ascii && cli.output != "clipboard" {
+        if !cli.silent {
+            warn("ASCII snapshot only supports copying to clipboard");
+        }
+        return Ok(());
+    }
+
+    let output_format = parse_output_format(&cli.output)?;
+    let prepared_input = prepare_input(&cli)?;
+
+    let (config_value, created_home_config) = load_effective_config_value(&cli)?;
+    let effective = build_effective_config(&config_value, &cli)?;
+
+    match cli.snapshot_type {
+        SnapshotType::Ascii => {
+            let PreparedInput::Text(prepared_text) = prepared_input else {
+                return Err("ASCII snapshot only supports code snippets".to_string());
+            };
+            let ascii = prepared_text
+                .lines
+                .iter()
+                .map(|line| line.text())
+                .collect::<Vec<_>>()
+                .join("\n");
+            write_clipboard_text(&ascii)?;
+        }
+        SnapshotType::Image => {
+            let png_bytes = match prepared_input {
+                PreparedInput::Text(prepared_text) => {
+                    let snapshot_settings = build_snapshot_settings(&effective, &cli, &prepared_text)?;
+                    render_text_snapshot(
+                        &prepared_text.lines,
+                        prepared_text.language_hint.as_deref(),
+                        prepared_text.path_hint.as_deref(),
+                        &snapshot_settings,
+                    )?
+                }
+                PreparedInput::Image(image_bytes) => {
+                    let image_settings = build_image_settings(&effective, &cli)?;
+                    render_image_snapshot(&image_bytes, &image_settings)?
+                }
+            };
+
+            match output_format {
+                OutputFormat::Clipboard => write_clipboard_image(&png_bytes)?,
+                OutputFormat::Png(path) => fs::write(&path, &png_bytes)
+                    .map_err(|err| err.to_string())?,
+                OutputFormat::Svg(path) => {
+                    let svg = render::png_bytes_to_svg(&png_bytes);
+                    fs::write(&path, svg).map_err(|err| err.to_string())?;
+                }
+                OutputFormat::Html(path) => {
+                    let html = render::png_bytes_to_html(&png_bytes);
+                    fs::write(&path, html).map_err(|err| err.to_string())?;
+                }
+            }
+        }
+    }
+
+    if !cli.silent {
+        if let Some(path) = created_home_config {
+            info(&format!(
+                "Automated created config file at \"{}\"",
+                path.display()
+            ));
+        }
+        success(&format!(
+            "Snapshot saved to {} successful!",
+            cli.output
+        ));
+    }
+
+    Ok(())
+}
+
+fn parse_output_format(output: &str) -> Result<OutputFormat, String> {
+    if output == "clipboard" {
+        return Ok(OutputFormat::Clipboard);
+    }
+
+    let path = PathBuf::from(output);
+    let ext = path.extension().and_then(|ext| ext.to_str());
+    match ext {
+        Some("png") => Ok(OutputFormat::Png(path)),
+        Some("svg") => Ok(OutputFormat::Svg(path)),
+        Some("html") => Ok(OutputFormat::Html(path)),
+        _ => Err("Unsupported output format".to_string()),
+    }
+}
+
+fn prepare_input(cli: &Cli) -> Result<PreparedInput, String> {
+    if !cli.execute.is_empty() {
+        return prepare_execute_input(cli).map(PreparedInput::Text);
+    }
+
+    if let Some(path) = &cli.from_file {
+        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
+        return prepare_plain_text(text, cli, Some(path.to_string_lossy().into_owned()));
+    }
+
+    if let Some(from_code) = &cli.from_code {
+        let text = match from_code {
+            Some(code) => code.clone(),
+            None => read_stdin_to_string().map_err(|err| err.to_string())?,
+        };
+        return prepare_plain_text(text, cli, cli.file_path.clone());
+    }
+
+    if let Some(from_image) = &cli.from_image {
+        let bytes = match from_image {
+            Some(image) => image.as_bytes().to_vec(),
+            None => read_stdin_to_bytes().map_err(|err| err.to_string())?,
+        };
+        return Ok(PreparedInput::Image(bytes));
+    }
+
+    if cli.from_clipboard {
+        return read_clipboard_input();
+    }
+
+    Err("No code snippet provided".to_string())
+}
+
+fn prepare_execute_input(cli: &Cli) -> Result<PreparedText, String> {
+    let mut lines = Vec::new();
+    let mut line_no = 1usize;
+
+    for command in &cli.execute {
+        lines.push(RenderSourceLine::rich(
+            line_no,
+            vec![
+                render::StyledChunk::new("> ", [0xff, 0x79, 0xc6, 0xff]),
+                shell_command_chunks(command),
+            ]
+            .into_iter()
+            .flatten()
+            .collect(),
+        ));
+        line_no += 1;
+
+        if cli.skip {
+            continue;
+        }
+
+        let output = Command::new("sh")
+            .arg("-lc")
+            .arg(format!("{command} 2>&1"))
+            .output()
+            .map_err(|err| err.to_string())?;
+        let merged = String::from_utf8_lossy(&output.stdout);
+        for line in split_lines_preserve_empty(&merged) {
+            lines.push(RenderSourceLine::rich(
+                line_no,
+                vec![render::StyledChunk::new(line, [0x8b, 0x94, 0xa7, 0xff])],
+            ));
+            line_no += 1;
+        }
+    }
+
+    let (lines, displayed_start_line) = apply_range_to_render_lines(lines, cli.range.as_deref())?;
+    Ok(PreparedText {
+        lines,
+        language_hint: None,
+        path_hint: None,
+        displayed_start_line,
+    })
+}
+
+fn prepare_plain_text(
+    text: String,
+    cli: &Cli,
+    path_hint: Option<String>,
+) -> Result<PreparedInput, String> {
+    let mut lines = split_lines_preserve_empty(&text)
+        .into_iter()
+        .enumerate()
+        .map(|(index, line)| RenderSourceLine::plain(index + 1, line.to_string()))
+        .collect::<Vec<_>>();
+    let (lines_after_range, displayed_start_line) =
+        apply_range_to_render_lines(lines, cli.range.as_deref())?;
+    lines = lines_after_range;
+
+    let language_hint = cli
+        .language
+        .clone()
+        .or_else(|| path_hint.clone())
+        .or_else(|| cli.file_path.clone());
+
+    Ok(PreparedInput::Text(PreparedText {
+        lines,
+        language_hint,
+        path_hint,
+        displayed_start_line,
+    }))
+}
+
+fn read_clipboard_input() -> Result<PreparedInput, String> {
+    Err(format!(
+        "Unknown error while interacting with the clipboard: {}",
+        CLIPBOARD_HEADLESS_ERROR
+    ))
+}
+
+fn apply_range_to_render_lines(
+    lines: Vec<RenderSourceLine>,
+    spec: Option<&str>,
+) -> Result<(Vec<RenderSourceLine>, usize), String> {
+    let Some(spec) = spec else {
+        let start = lines.first().map_or(1, RenderSourceLine::original_number);
+        return Ok((lines, start));
+    };
+    let range = RangeSpec::parse(spec)?;
+    let mut visible = Vec::new();
+    for line in lines {
+        if range.contains(line.original_number()) {
+            visible.push(line);
+        }
+    }
+    let displayed_start_line = visible
+        .first()
+        .map_or(range.start.unwrap_or(1), RenderSourceLine::original_number);
+    Ok((visible, displayed_start_line))
+}
+
+fn build_snapshot_settings(
+    effective: &EffectiveConfig,
+    cli: &Cli,
+    prepared: &PreparedText,
+) -> Result<SnapshotSettings, String> {
+    let line_number_color = effective.line_number_color;
+    let add_line_color = effective.add_line_color;
+    let delete_line_color = effective.delete_line_color;
+    let highlight_range_color = effective.highlight_range_color;
+
+    let mut backgrounds = BTreeMap::new();
+
+    if let Some(raw) = &cli.raw_highlight_lines {
+        for (range, color) in parse_raw_highlights(raw)? {
+            for line in prepared.lines.iter().map(RenderSourceLine::original_number) {
+                if range.contains(&line) {
+                    backgrounds.insert(line, LineRenderBackground(color));
+                }
+            }
+        }
+    }
+
+    if let Some(range_str) = &cli.highlight_range {
+        let range = RangeSpec::parse(range_str)?;
+        let visible_numbers = prepared
+            .lines
+            .iter()
+            .map(RenderSourceLine::original_number)
+            .collect::<Vec<_>>();
+        for (index, line) in visible_numbers.iter().enumerate() {
+            let number = if cli.relative_highlight_range {
+                index + 1
+            } else {
+                *line
+            };
+            if range.contains(number) {
+                backgrounds
+                    .entry(*line)
+                    .or_insert(LineRenderBackground(highlight_range_color));
+            }
+        }
+    }
+
+    for line_no in parse_line_numbers(&cli.add_line)? {
+        backgrounds.insert(line_no, LineRenderBackground(add_line_color));
+    }
+    for line_no in parse_line_numbers(&cli.delete_line)? {
+        backgrounds.insert(line_no, LineRenderBackground(delete_line_color));
+    }
+
+    let displayed_start_line = match &cli.start_line_number {
+        Some(value) => value.parse::<usize>().map_err(|err| err.to_string())?,
+        None => prepared.displayed_start_line,
+    };
+
+    Ok(SnapshotSettings {
+        theme: effective.theme,
+        mac_window_bar: effective.mac_window_bar,
+        shadow_radius: effective.shadow_radius,
+        shadow_color: effective.shadow_color,
+        margin_x: effective.margin_x,
+        margin_y: effective.margin_y,
+        border_color: effective.border_color,
+        title: cli.title.clone(),
+        title_color: effective.title_color,
+        watermark: (!effective.watermark_text.is_empty()).then(|| effective.watermark_text.clone()),
+        watermark_color: effective.watermark_color,
+        breadcrumbs: if effective.breadcrumbs_enable {
+            prepared.path_hint.as_ref().map(|path| {
+                path.replace('/', &effective.breadcrumbs_separator)
+            })
+        } else {
+            None
+        },
+        breadcrumbs_color: effective.breadcrumbs_color,
+        has_line_numbers: cli.has_line_number,
+        displayed_start_line,
+        line_number_color,
+        scale_factor: effective.scale_factor,
+        line_backgrounds: backgrounds,
+        code_font_family: effective.code_font_family.clone(),
+        title_font_family: effective.title_font_family.clone(),
+        watermark_font_family: effective.watermark_font_family.clone(),
+        breadcrumbs_font_family: effective.breadcrumbs_font_family.clone(),
+    })
+}
+
+fn build_image_settings(
+    effective: &EffectiveConfig,
+    cli: &Cli,
+) -> Result<ImageRenderSettings, String> {
+    Ok(ImageRenderSettings {
+        margin_x: effective.margin_x,
+        margin_y: effective.margin_y,
+        shadow_radius: effective.shadow_radius,
+        shadow_color: effective.shadow_color,
+        watermark: cli
+            .watermark
+            .clone()
