+            window_h,
+            (WINDOW_RADIUS * settings.scale_factor as f32).round() as i32,
+            settings.shadow_color,
+        );
+    });
+    overlay(&mut canvas, &shadow, 0, 0);
+
+    fill_rounded_rect(
+        &mut canvas,
+        window_x,
+        window_y,
+        window_w,
+        window_h,
+        (WINDOW_RADIUS * settings.scale_factor as f32).round() as i32,
+        settings.border_color,
+    );
+    fill_rounded_rect(
+        &mut canvas,
+        window_x + (BORDER_WIDTH * settings.scale_factor as f32).round() as i32,
+        window_y + (BORDER_WIDTH * settings.scale_factor as f32).round() as i32,
+        window_w - 2 * (BORDER_WIDTH * settings.scale_factor as f32).round() as i32,
+        window_h - 2 * (BORDER_WIDTH * settings.scale_factor as f32).round() as i32,
+        (INNER_CORNER_RADIUS * settings.scale_factor as f32).round() as i32,
+        WINDOW_BACKGROUND,
+    );
+
+    if settings.mac_window_bar {
+        draw_window_circles(&mut canvas, settings.scale_factor, window_x, window_y);
+    }
+
+    if let Some(title) = &settings.title {
+        let title_width = measure_text(&ui_font, small_scale, title);
+        let x = window_x as f32 + window_width / 2.0 - title_width / 2.0;
+        let y = window_y as f32 + 6.0 * settings.scale_factor as f32;
+        draw_text_mut(
+            &mut canvas,
+            Rgba(settings.title_color),
+            x.round() as i32,
+            y.round() as i32,
+            small_scale,
+            &ui_font,
+            title,
+        );
+    }
+
+    if let Some(breadcrumbs) = &settings.breadcrumbs {
+        let x = window_x as f32 + LEFT_PADDING * settings.scale_factor as f32;
+        let y = window_y as f32 + 28.0 * settings.scale_factor as f32;
+        draw_text_mut(
+            &mut canvas,
+            Rgba(settings.breadcrumbs_color),
+            x.round() as i32,
+            y.round() as i32,
+            small_scale,
+            &breadcrumb_font,
+            breadcrumbs,
+        );
+    }
+
+    let code_x = window_x as f32 + LEFT_PADDING * settings.scale_factor as f32;
+    let code_start_y = window_y as f32
+        + if settings.mac_window_bar {
+            TOP_PADDING_BAR * settings.scale_factor as f32
+        } else {
+            TOP_PADDING_NO_BAR * settings.scale_factor as f32
+        }
+        + if settings.breadcrumbs.is_some() {
+            BREADCRUMBS_HEIGHT * settings.scale_factor as f32
+        } else {
+            0.0
+        };
+    let full_line_width = window_w as f32 - 2.0 * BORDER_WIDTH * settings.scale_factor as f32;
+
+    for (index, line) in highlighted.iter().enumerate() {
+        let y = code_start_y + index as f32 * LINE_HEIGHT * settings.scale_factor as f32;
+        if let Some(background) = settings
+            .line_backgrounds
+            .get(&line.original_number)
+            .copied()
+        {
+            fill_rect_alpha(
+                &mut canvas,
+                window_x + (BORDER_WIDTH * settings.scale_factor as f32).round() as i32,
+                y.round() as i32 - settings.scale_factor as i32,
+                full_line_width.round() as i32,
+                (LINE_HEIGHT * settings.scale_factor as f32).round() as i32 + settings.scale_factor as i32,
+                background.0,
+            );
+        }
+
+        let mut x = code_x;
+        if settings.has_line_numbers {
+            let number = settings.displayed_start_line + index;
+            draw_text_mut(
+                &mut canvas,
+                Rgba(settings.line_number_color),
+                x.round() as i32,
+                y.round() as i32,
+                small_scale,
+                &ui_font,
+                &number.to_string(),
+            );
+            x += line_number_width;
+        }
+
+        for chunk in &line.chunks {
+            if chunk.text.is_empty() {
+                continue;
+            }
+            draw_text_mut(
+                &mut canvas,
+                Rgba(chunk.color),
+                x.round() as i32,
+                y.round() as i32,
+                code_scale,
+                &code_font,
+                &chunk.text,
+            );
+            x += measure_text(&code_font, code_scale, &chunk.text);
+        }
+    }
+
+    if let Some(watermark) = &settings.watermark {
+        let watermark_width = measure_text(&watermark_font, watermark_scale, watermark);
+        let x = canvas_width as f32 / 2.0 - watermark_width / 2.0;
+        let y = canvas_height as f32
+            - (settings.margin_y as f32 * settings.scale_factor as f32 * 0.68)
+            - WATERMARK_FONT_SIZE * settings.scale_factor as f32 * 0.1;
+        draw_text_mut(
+            &mut canvas,
+            Rgba(settings.watermark_color),
+            x.round() as i32,
+            y.round() as i32,
+            watermark_scale,
+            &watermark_font,
+            watermark,
+        );
+    }
+
+    encode_png(&DynamicImage::ImageRgba8(canvas))
+}
+
+pub fn render_image_snapshot(
+    image_bytes: &[u8],
+    settings: &ImageRenderSettings,
+) -> Result<Vec<u8>, String> {
+    let image = decode_png(image_bytes)?;
+    let watermark_font = load_font(&settings.watermark_font_family, false)?;
+    let watermark_scale = PxScale::from(WATERMARK_FONT_SIZE * settings.scale_factor as f32);
+    let image_w = image.width() as f32 * settings.scale_factor as f32;
+    let image_h = image.height() as f32 * settings.scale_factor as f32;
+    let margin_x = settings.margin_x as f32 * settings.scale_factor as f32;
+    let margin_y = settings.margin_y as f32 * settings.scale_factor as f32;
+    let canvas_w = (image_w + margin_x * 2.0).round() as u32;
+    let canvas_h = (image_h + margin_y * 2.0).round() as u32;
+
+    let mut canvas = gradient_background(canvas_w, canvas_h);
+    let scaled_image = image.resize_exact(
+        image_w.round() as u32,
+        image_h.round() as u32,
+        image::imageops::FilterType::CatmullRom,
+    );
+
+    let shadow = shadow_layer(canvas_w, canvas_h, settings.shadow_color, settings.shadow_radius, |img| {
+        stamp_image_alpha(
+            img,
+            scaled_image.to_rgba8().as_ref(),
+            margin_x.round() as i32,
+            margin_y.round() as i32,
+            settings.shadow_color,
+        );
+    });
+    overlay(&mut canvas, &shadow, 0, 0);
+    overlay(
+        &mut canvas,
+        &scaled_image.to_rgba8(),
+        margin_x.round() as i64,
+        margin_y.round() as i64,
+    );
+
+    if !settings.watermark.is_empty() {
+        let width = measure_text(&watermark_font, watermark_scale, &settings.watermark);
+        let x = canvas_w as f32 / 2.0 - width / 2.0;
+        let y = canvas_h as f32
+            - (settings.margin_y as f32 * settings.scale_factor as f32 * 0.68)
+            - WATERMARK_FONT_SIZE * settings.scale_factor as f32 * 0.1;
+        draw_text_mut(
+            &mut canvas,
+            Rgba(settings.watermark_color),
+            x.round() as i32,
+            y.round() as i32,
+            watermark_scale,
+            &watermark_font,
+            &settings.watermark,
+        );
+    }
+
+    encode_png(&DynamicImage::ImageRgba8(canvas))
+}
