+pub fn color_from_hex(input: &str) -> Option<[u8; 4]> {
+    let hex = input.strip_prefix('#')?;
+    match hex.len() {
+        6 => {
+            let value = u32::from_str_radix(hex, 16).ok()?;
+            Some([
+                ((value >> 16) & 0xff) as u8,
+                ((value >> 8) & 0xff) as u8,
+                (value & 0xff) as u8,
+                0xff,
+            ])
+        }
+        8 => {
+            let value = u32::from_str_radix(hex, 16).ok()?;
+            Some([
+                ((value >> 24) & 0xff) as u8,
+                ((value >> 16) & 0xff) as u8,
+                ((value >> 8) & 0xff) as u8,
+                (value & 0xff) as u8,
+            ])
+        }
+        _ => None,
+    }
+}
