+fn add_theme_rule(
+    theme: &mut Theme,
+    scope: &str,
+    foreground: Option<Color>,
+    font_style: Option<FontStyle>,
+) {
+    let selectors = ScopeSelectors::from_str(scope).expect("valid scope");
+    theme.scopes.push(ThemeItem {
+        scope: selectors,
+        style: StyleModifier {
+            foreground,
+            background: None,
+            font_style,
+        },
+    });
+}
