use syntect::{highlighting::ScopeSelectors, parsing::Scope};

const WINDOW_BACKGROUND: [u8; 4] = [40, 44, 62, 255];
const DEFAULT_FOREGROUND: [u8; 4] = [248, 248, 242, 255];
const CODE_FONT_SIZE: f32 = 16.0;
const SMALL_FONT_SIZE: f32 = 12.0;
const WATERMARK_FONT_SIZE: f32 = 42.0;
const LINE_HEIGHT: f32 = 18.0;
const LEFT_PADDING: f32 = 18.0;
const RIGHT_PADDING: f32 = 18.0;
const TOP_PADDING_NO_BAR: f32 = 24.0;
const TOP_PADDING_BAR: f32 = 48.0;
const BOTTOM_PADDING: f32 = 78.0;
const BREADCRUMBS_HEIGHT: f32 = 15.0;
const WINDOW_MIN_WIDTH: f32 = 354.0;
const WINDOW_RADIUS: f32 = 12.0;
const BORDER_WIDTH: f32 = 1.0;
const MAC_BAR_HEIGHT: f32 = 24.0;
const INNER_CORNER_RADIUS: f32 = WINDOW_RADIUS - BORDER_WIDTH;
const CIRCLE_RADIUS: f32 = 6.0;
const CIRCLE_GAP: f32 = 8.0;
const CIRCLE_TOP: f32 = 11.0;
const CIRCLE_LEFT: f32 = 20.0;
const BACKGROUND_LEFT: [u8; 4] = [107, 203, 165, 255];
const BACKGROUND_RIGHT: [u8; 4] = [202, 244, 194, 255];

#[derive(Clone, Debug)]
pub struct StyledChunk {
    pub text: String,
    pub color: [u8; 4],
}

impl StyledChunk {
    pub fn new(text: impl Into<String>, color: [u8; 4]) -> Self {
        Self {
            text: text.into(),
            color,
        }
    }
}

#[derive(Clone, Debug)]
pub enum RenderSourceContent {
    Plain(String),
    Rich(Vec<StyledChunk>),
}

#[derive(Clone, Debug)]
pub struct RenderSourceLine {
    original_number: usize,
    content: RenderSourceContent,
}

impl RenderSourceLine {
    pub fn plain(original_number: usize, text: impl Into<String>) -> Self {
        Self {
            original_number,
            content: RenderSourceContent::Plain(text.into()),
        }
    }

    pub fn rich(original_number: usize, chunks: Vec<StyledChunk>) -> Self {
        Self {
            original_number,
            content: RenderSourceContent::Rich(chunks),
        }
    }

    pub fn original_number(&self) -> usize {
        self.original_number
    }

    pub fn text(&self) -> &str {
        match &self.content {
            RenderSourceContent::Plain(text) => text,
            RenderSourceContent::Rich(chunks) => {
                // Renderers only call this on rich lines for ASCII output.
                // Joining on-demand keeps the source struct compact.
                Box::leak(
                    chunks
                        .iter()
                        .map(|chunk| chunk.text.as_str())
                        .collect::<String>()
                        .into_boxed_str(),
                )
            }
        }
    }

    fn content(&self) -> &RenderSourceContent {
        &self.content
    }
}

#[derive(Clone, Copy, Debug)]
