pub fn color_from_hex(input: &str) -> Option<[u8; 4]> {
    let hex = input.strip_prefix('#')?;
    match hex.len() {
        6 => {
            let value = u32::from_str_radix(hex, 16).ok()?;
            Some([
                ((value >> 16) & 0xff) as u8,
                ((value >> 8) & 0xff) as u8,
                (value & 0xff) as u8,
                0xff,
            ])
        }
        8 => {
            let value = u32::from_str_radix(hex, 16).ok()?;
            Some([
                ((value >> 24) & 0xff) as u8,
                ((value >> 16) & 0xff) as u8,
                ((value >> 8) & 0xff) as u8,
                (value & 0xff) as u8,
            ])
        }
        _ => None,
    }
}

fn load_font(family: &str, monospace: bool) -> Result<FontArc, String> {
    let preferred = if monospace || family.to_ascii_lowercase().contains("mono") {
        "/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf"
    } else {
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"
    };
    let bytes = std::fs::read(preferred).map_err(|err| err.to_string())?;
    FontArc::try_from_vec(bytes).map_err(|_| "Failed to load font".to_string())
}

fn decode_png(bytes: &[u8]) -> Result<DynamicImage, String> {
    let decoder = Decoder::new(bytes);
    let mut reader = decoder.read_info().map_err(|err| err.to_string())?;
    let mut buf = vec![0; reader.output_buffer_size()];
    let info = reader.next_frame(&mut buf).map_err(|err| err.to_string())?;
    let width = info.width;
    let height = info.height;
    let bytes = &buf[..info.buffer_size()];

    let mut rgba = Vec::new();
    match info.color_type {
        png::ColorType::Rgba => rgba.extend_from_slice(bytes),
        png::ColorType::Rgb => {
            for chunk in bytes.chunks_exact(3) {
                rgba.extend_from_slice(chunk);
                rgba.push(255);
            }
        }
        png::ColorType::GrayscaleAlpha => {
            for chunk in bytes.chunks_exact(2) {
                rgba.extend_from_slice(&[chunk[0], chunk[0], chunk[0], chunk[1]]);
            }
        }
        png::ColorType::Grayscale => {
            for value in bytes {
                rgba.extend_from_slice(&[*value, *value, *value, 255]);
            }
        }
        _ => return Err("Unsupported PNG color type".to_string()),
    }

    let image = RgbaImage::from_raw(width, height, rgba)
        .ok_or_else(|| "Failed to decode image".to_string())?;
    Ok(DynamicImage::ImageRgba8(image))
}

fn encode_png(image: &DynamicImage) -> Result<Vec<u8>, String> {
    let mut bytes = Vec::new();
    image
        .write_to(&mut std::io::Cursor::new(&mut bytes), ImageFormat::Png)
        .map_err(|err| err.to_string())?;
    Ok(bytes)
}

fn gradient_background(width: u32, height: u32) -> RgbaImage {
    let mut image = ImageBuffer::new(width, height);
    for (x, _, pixel) in image.enumerate_pixels_mut() {
        let t = if width <= 1 {
            0.0
        } else {
            x as f32 / (width - 1) as f32
        };
        *pixel = Rgba(lerp_color(BACKGROUND_LEFT, BACKGROUND_RIGHT, t));
    }
    image
}

fn lerp_color(a: [u8; 4], b: [u8; 4], t: f32) -> [u8; 4] {
    [
        lerp_u8(a[0], b[0], t),
        lerp_u8(a[1], b[1], t),
        lerp_u8(a[2], b[2], t),
        lerp_u8(a[3], b[3], t),
    ]
}

fn lerp_u8(a: u8, b: u8, t: f32) -> u8 {
    ((a as f32) + (b as f32 - a as f32) * t).round() as u8
}

fn highlight_lines(
    lines: &[RenderSourceLine],
    language_hint: Option<&str>,
    path_hint: Option<&str>,
    theme_kind: ThemeKind,
) -> Result<Vec<HighlightedLine>, String> {
    let syntax_set = SyntaxSet::load_defaults_newlines();
    let syntax = detect_syntax(&syntax_set, language_hint, path_hint);

    let mut highlighter = if theme_kind == ThemeKind::Plain {
        None
    } else {
        syntax.map(|syntax| HighlightLines::new(syntax, &build_theme(theme_kind)))
    };

    let mut result = Vec::new();
    for line in lines {
        let chunks = match line.content() {
            RenderSourceContent::Rich(chunks) => chunks.clone(),
            RenderSourceContent::Plain(text) => {
                if let Some(highlighter) = &mut highlighter {
                    let mut line_chunks = Vec::new();
                    let owned = format!("{text}\n");
                    let highlighted = highlighter
                        .highlight_line(&owned, &syntax_set)
                        .map_err(|err| err.to_string())?;
                    for (style, text) in highlighted {
                        if text == "\n" {
                            continue;
                        }
                        line_chunks.push(StyledChunk::new(
                            text.to_string(),
                            [
                                style.foreground.r,
                                style.foreground.g,
                                style.foreground.b,
                                255,
                            ],
                        ));
                    }
                    if line_chunks.is_empty() {
                        line_chunks.push(StyledChunk::new("", DEFAULT_FOREGROUND));
                    }
                    line_chunks
                } else {
                    vec![StyledChunk::new(text, DEFAULT_FOREGROUND)]
                }
            }
        };

        result.push(HighlightedLine {
            original_number: line.original_number(),
            chunks,
        });
    }
    Ok(result)
}

fn detect_syntax<'a>(
    syntax_set: &'a SyntaxSet,
    language_hint: Option<&str>,
    path_hint: Option<&str>,
) -> Option<&'a syntect::parsing::SyntaxReference> {
    if let Some(language) = language_hint {
        if let Some(path) = Path::new(language).extension().and_then(|ext| ext.to_str()) {
            if let Some(syntax) = syntax_set.find_syntax_by_extension(path) {
                return Some(syntax);
            }
        }
        if let Some(syntax) = syntax_set.find_syntax_by_token(language) {
            return Some(syntax);
        }
        if let Some(syntax) = syntax_set.find_syntax_by_name(language) {
            return Some(syntax);
        }
    }

    if let Some(path_hint) = path_hint {
        if let Some(extension) = Path::new(path_hint).extension().and_then(|ext| ext.to_str()) {
            if let Some(syntax) = syntax_set.find_syntax_by_extension(extension) {
                return Some(syntax);
            }
        }
    }

    None
}

fn build_theme(theme_kind: ThemeKind) -> Theme {
    let mut theme = Theme {
        name: None,
        author: None,
        settings: ThemeSettings {
