        },
        scopes: Vec::new(),
    };

    let palette = match theme_kind {
        ThemeKind::Candy | ThemeKind::Dracula => Palette {
            keyword: rgb(255, 121, 198),
            function: rgb(128, 229, 255),
            string: rgb(241, 250, 140),
            number: rgb(189, 147, 249),
