            list_marker: rgb(255, 121, 198),
        },
        ThemeKind::Nord | ThemeKind::OneDark | ThemeKind::GithubDark | ThemeKind::GithubLight => Palette {
            keyword: rgb(191, 97, 106),
            function: rgb(136, 192, 208),
            string: rgb(163, 190, 140),
            number: rgb(180, 142, 173),
            comment: rgb(94, 129, 172),
            heading: rgb(136, 192, 208),
            list_marker: rgb(191, 97, 106),
        },
        ThemeKind::Monokai | ThemeKind::SolarizedDark | ThemeKind::SolarizedLight | ThemeKind::Plain => Palette {
            keyword: rgb(249, 38, 114),
            function: rgb(102, 217, 239),
            string: rgb(230, 219, 116),
            number: rgb(174, 129, 255),
            comment: rgb(117, 113, 94),
            heading: rgb(102, 217, 239),
            list_marker: rgb(249, 38, 114),
        },
    };

    add_theme_rule(&mut theme, "keyword", Some(palette.keyword), Some(FontStyle::BOLD));
    add_theme_rule(&mut theme, "storage", Some(palette.keyword), Some(FontStyle::BOLD));
    add_theme_rule(&mut theme, "entity.name.function", Some(palette.function), None);
    add_theme_rule(&mut theme, "support.function", Some(palette.function), None);
    add_theme_rule(&mut theme, "string", Some(palette.string), None);
    add_theme_rule(&mut theme, "constant.numeric", Some(palette.number), None);
    add_theme_rule(&mut theme, "comment", Some(palette.comment), None);
    add_theme_rule(&mut theme, "markup.heading", Some(palette.heading), Some(FontStyle::BOLD));
    add_theme_rule(&mut theme, "punctuation.definition.list", Some(palette.list_marker), None);
    add_theme_rule(&mut theme, "markup.list", Some(palette.list_marker), None);

    theme
}

fn add_theme_rule(
    theme: &mut Theme,
    scope: &str,
    foreground: Option<Color>,
    font_style: Option<FontStyle>,
) {
    let selectors = ScopeSelectors::from_str(scope).expect("valid scope");
    theme.scopes.push(ThemeItem {
        scope: selectors,
        style: StyleModifier {
            foreground,
            background: None,
            font_style,
        },
    });
}

fn rgb(r: u8, g: u8, b: u8) -> Color {
    Color { r, g, b, a: 0xff }
}

fn measure_text(font: &FontArc, scale: PxScale, text: &str) -> f32 {
    let (width, _) = text_size(scale, font, text);
    width as f32
}

fn measure_chunks(font: &FontArc, scale: PxScale, chunks: &[StyledChunk]) -> f32 {
    chunks
        .iter()
        .map(|chunk| measure_text(font, scale, &chunk.text))
        .sum()
}

fn shadow_layer(
    width: u32,
    height: u32,
    shadow_color: [u8; 4],
    shadow_radius: f32,
    painter: impl FnOnce(&mut RgbaImage),
) -> RgbaImage {
    let mut layer = RgbaImage::from_pixel(width, height, Rgba([0, 0, 0, 0]));
    painter(&mut layer);
    blur(&layer, shadow_radius.max(1.0) / 2.0)
}

fn draw_window_circles(canvas: &mut RgbaImage, scale_factor: u32, window_x: i32, window_y: i32) {
    let radius = (CIRCLE_RADIUS * scale_factor as f32).round() as i32;
    let top = window_y + (CIRCLE_TOP * scale_factor as f32).round() as i32;
    let left = window_x + (CIRCLE_LEFT * scale_factor as f32).round() as i32;
    let gap = (CIRCLE_GAP * scale_factor as f32).round() as i32;
    let colors = [
        [255, 95, 86, 255],
        [255, 189, 46, 255],
        [39, 201, 63, 255],
    ];
    for (index, color) in colors.iter().enumerate() {
        fill_circle(
            canvas,
            left + index as i32 * (radius * 2 + gap),
            top,
            radius,
            *color,
        );
    }
}

fn fill_circle(image: &mut RgbaImage, cx: i32, cy: i32, radius: i32, color: [u8; 4]) {
    for y in (cy - radius)..=(cy + radius) {
        for x in (cx - radius)..=(cx + radius) {
            let dx = x - cx;
            let dy = y - cy;
            if dx * dx + dy * dy <= radius * radius {
                blend_pixel(image, x, y, color);
            }
        }
    }
}

fn fill_rect_alpha(
    image: &mut RgbaImage,
    x: i32,
    y: i32,
    width: i32,
    height: i32,
    color: [u8; 4],
) {
    for yy in y.max(0)..(y + height).min(image.height() as i32) {
        for xx in x.max(0)..(x + width).min(image.width() as i32) {
            blend_pixel(image, xx, yy, color);
        }
    }
}

fn fill_rounded_rect(
    image: &mut RgbaImage,
    x: i32,
    y: i32,
    width: i32,
    height: i32,
    radius: i32,
    color: [u8; 4],
) {
    let radius = radius.max(0);
    for yy in y.max(0)..(y + height).min(image.height() as i32) {
        for xx in x.max(0)..(x + width).min(image.width() as i32) {
            let inside = if radius == 0 {
                true
            } else {
                let local_x = xx - x;
                let local_y = yy - y;
                let rx = if local_x < radius {
                    radius - local_x
                } else if local_x >= width - radius {
                    local_x - (width - radius - 1)
                } else {
                    0
                };
                let ry = if local_y < radius {
                    radius - local_y
                } else if local_y >= height - radius {
                    local_y - (height - radius - 1)
                } else {
                    0
                };
                rx * rx + ry * ry <= radius * radius
            };
            if inside {
                blend_pixel(image, xx, yy, color);
            }
        }
    }
}

fn stamp_image_alpha(
    image: &mut RgbaImage,
    source: &[u8],
    x: i32,
    y: i32,
    color: [u8; 4],
) {
    let pixels = source.chunks_exact(4);
    let width = ((source.len() / 4) as f32).sqrt() as i32;
    for (index, pixel) in pixels.enumerate() {
        let sx = (index as i32) % width;
        let sy = (index as i32) / width;
        let alpha = pixel[3];
        if alpha == 0 {
            continue;
        }
        let mut shadow = color;
        shadow[3] = ((shadow[3] as u16 * alpha as u16) / 255) as u8;
        blend_pixel(image, x + sx, y + sy, shadow);
    }
}

fn blend_pixel(image: &mut RgbaImage, x: i32, y: i32, color: [u8; 4]) {
    if x < 0 || y < 0 || x >= image.width() as i32 || y >= image.height() as i32 {
        return;
    }
    let dst = image.get_pixel_mut(x as u32, y as u32);
    let alpha = color[3] as f32 / 255.0;
    let inv = 1.0 - alpha;
    let blended = [
        (color[0] as f32 * alpha + dst[0] as f32 * inv).round() as u8,
        (color[1] as f32 * alpha + dst[1] as f32 * inv).round() as u8,
        (color[2] as f32 * alpha + dst[2] as f32 * inv).round() as u8,
        255,
    ];
    *dst = Rgba(blended);
}

#[derive(Clone, Debug)]
struct HighlightedLine {
    original_number: usize,
    chunks: Vec<StyledChunk>,
}

#[derive(Clone, Copy)]
struct Palette {
    keyword: Color,
    function: Color,
    string: Color,
    number: Color,
    comment: Color,
    heading: Color,
    list_marker: Color,
}

