fn load_effective_config_value(cli: &Cli) -> Result<(Value, Option<PathBuf>), String> {
    let default_value: Value =
        serde_json::from_str(DEFAULT_CONFIG_JSON).map_err(|err| err.to_string())?;

    let home_path = home_config_path()?;
    let mut created_path = None;
    if !home_path.exists() {
        if let Some(parent) = home_path.parent() {
            fs::create_dir_all(parent).map_err(|err| err.to_string())?;
        }
        fs::write(&home_path, DEFAULT_CONFIG_JSON).map_err(|err| err.to_string())?;
        created_path = Some(home_path.clone());
    }

    let mut merged = default_value;
    let home_value = read_json_value(&home_path)?;
    deep_merge(&mut merged, home_value);

    if let Some(path) = &cli.config {
        let cli_value = read_json_value(path)?;
        deep_merge(&mut merged, cli_value);
    }

    Ok((merged, created_path))
}

