fn parse_raw_highlights(
    raw: &str,
) -> Result<Vec<(BTreeSet<usize>, [u8; 4])>, String> {
    let value: Value = serde_json::from_str(raw).map_err(|err| err.to_string())?;
    let items = value
        .as_array()
        .ok_or_else(|| "raw highlight must be an array".to_string())?;
    let mut results = Vec::new();

    for item in items {
        let parts = item
            .as_array()
            .ok_or_else(|| "highlight item must be an array".to_string())?;
        match parts.as_slice() {
            [line, color] => {
                let line_no = json_to_usize(line)?;
                let color = parse_color_string(color.as_str().ok_or_else(|| {
                    "highlight color must be a string".to_string()
                })?)?;
                results.push((BTreeSet::from([line_no]), color));
            }
            [start, end, color] => {
                let start = json_to_usize(start)?;
                let end = json_to_usize(end)?;
                let color = parse_color_string(color.as_str().ok_or_else(|| {
                    "highlight color must be a string".to_string()
                })?)?;
                let set = (start..=end).collect::<BTreeSet<_>>();
                results.push((set, color));
            }
            _ => return Err("invalid raw highlight entry".to_string()),
        }
    }

    Ok(results)
}

fn parse_line_numbers(values: &[String]) -> Result<Vec<usize>, String> {
