fn shell_command_chunks(command: &str) -> Vec<render::StyledChunk> {
    let mut parts = command.splitn(2, char::is_whitespace);
    let first = parts.next().unwrap_or_default();
    let rest = parts.next();

    let mut chunks = vec![render::StyledChunk::new(first, [0xa6, 0xe2, 0x7a, 0xff])];
    if let Some(rest) = rest {
        chunks.push(render::StyledChunk::new(" ", [0xf8, 0xf8, 0xf2, 0xff]));
        chunks.push(render::StyledChunk::new(rest, [0xf8, 0xf8, 0xf2, 0xff]));
    }
    chunks
}

