fn deep_merge(target: &mut Value, overlay: Value) {
    match (target, overlay) {
        (Value::Object(target_map), Value::Object(overlay_map)) => {
            for (key, overlay_value) in overlay_map {
                match target_map.get_mut(&key) {
                    Some(target_value) => deep_merge(target_value, overlay_value),
                    None => {
                        target_map.insert(key, overlay_value);
                    }
                }
            }
        }
        (target_slot, overlay_value) => *target_slot = overlay_value,
    }
}

fn get_value<'a>(value: &'a Value, path: &[&str]) -> &'a Value {
    let mut current = value;
    for key in path {
        current = &current[*key];
    }
    current
}

fn get_str<'a>(value: &'a Value, path: &[&str]) -> &'a str {
    get_value(value, path).as_str().unwrap_or_default()
}

fn get_bool(value: &Value, path: &[&str]) -> bool {
    get_value(value, path).as_bool().unwrap_or(false)
}

