#[derive(Clone, Copy, Debug)]
struct RangeSpec {
    start: Option<usize>,
    end: Option<usize>,
}

impl RangeSpec {
    fn parse(value: &str) -> Result<Self, String> {
        if let Some((start, end)) = value.split_once(':') {
            let start = if start.is_empty() {
                None
            } else {
                Some(start.parse::<usize>().map_err(|err| err.to_string())?)
            };
            let end = if end.is_empty() {
                None
            } else {
                Some(end.parse::<usize>().map_err(|err| err.to_string())?)
            };
            return Ok(Self { start, end });
        }

        let exact = value.parse::<usize>().map_err(|err| err.to_string())?;
        Ok(Self {
            start: Some(exact),
            end: Some(exact),
        })
    }

    fn contains(&self, value: usize) -> bool {
        if let Some(start) = self.start {
            if value < start {
                return false;
            }
        }
        if let Some(end) = self.end {
            if value > end {
                return false;
            }
        }
        true
    }
}

